/**
 * @hidden
 */
const normalizeSettings = ({ buttonCount = 10, info = true, type = 'numeric', pageSizes = false, previousNext = true, responsive = true }) => ({
    buttonCount,
    info,
    pageSizes,
    previousNext,
    type,
    responsive
});
/**
 * @hidden
 */
export const normalize = (settings) => normalizeSettings(settings === true ? {} : settings);
